'use strict';
// Portable copies of the existing, unchanged display GIFs. No extra asset folders required.
// Gojo uses the same approved source animations, without Hollow Purple.
const {gunzipSync}=require('node:zlib');
let catalog;
const PACKED="";
function bundledGif(characterId,state){
  catalog ||= JSON.parse(gunzipSync(Buffer.from(PACKED,'base64')).toString());
  const entry=catalog[characterId]?.[state];
  return entry ? Buffer.from(entry.gif,'base64') : null;
}
module.exports={bundledGif};
